func decodeBadge(name, path string, raw json.RawMessage, out *Badge) error {
	obj, err := jsonObject(name, path, raw)
	if err != nil {
		return err
	}
	if err := jsonKeys(name, path, obj, "kind"); err != nil {
		return err
	}
	r1, err := jsonNeed(name, path, obj, "kind")
	if err != nil {
		return err
	}
	var tag string
	if err := jsonRead(name, path, "kind", r1, &tag); err != nil {
		return err
	}
	switch tag {
	case "star":
		c := &BadgeStar{}
		if err := decodeBadgeStar(name, path, raw, c); err != nil {
			return err
		}
		*out = Badge{kind: BadgeKindStar, value: c}
	case "plain":
		*out = Badge{kind: BadgeKindPlain}
	default:
		return fmt.Errorf("%s: %skind: unknown case %s", name, path, tag)
	}
	return nil
}

